const crypto = require('crypto');
const item = $input.first().json;
const secret = $env.AUTOMATION_WEBHOOK_SECRET || '';
const given = String((item.headers || {})['x-helpdesk-signature'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(JSON.stringify(item.body)).digest('hex');
const a = Buffer.from(given);
const b = Buffer.from(expected);
if (!secret || a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid webhook signature');
}
return [{ json: Object.assign({}, item.body, { startedAt: new Date().toISOString() }) }];
